import{z as s,x as A,o,c as m,q as t,j as n,D as E,d as r,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"中位选民","description":"","frontmatter":{"title":"中位选民","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/median-voter.md","filePath":"econ/median-voter.md","lastUpdated":1791063341000}'),p={name:"econ/median-voter.md"};function d(D,a,c,_,h,x){const B=A("Mermaid");return o(),m("div",null,[a[2]||(a[2]=t('<h1 id="中位选民" tabindex="-1">中位选民 <a class="header-anchor" href="#中位选民" aria-label="Permalink to &quot;中位选民&quot;">​</a></h1><div class="epigraph"><p>若方案排成一条线、偏好单峰，多数两两比较有胜者，就是中位人的峰；两党为了赢，会把政纲收到这一点。</p><footer>—— 据 Black, On the Rationale of Group Decision-making, Journal of Political Economy, 1948；Downs, An Economic Theory of Democracy, 1957 整理</footer></div><p><a href="/econ/arrow-impossibility">上一课</a>（阿罗不可能定理）。无限制域、帕累托、IIA、非独裁不能共存；并点名单峰作为逃逸。本课不重写决定性联盟收缩。缺口是把逃逸做成均衡：一维方案、单峰偏好时，多数规则给出 Condorcet 胜者，且就是中位峰。Black 钉投票；Downs 把同一点写成两党竞争。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Arrow 的无限制域允许循环剖面，多数形不成排序。把方案写成 \\(\\mathbb{R}\\) 上的点（税率、公共支出规模），每人有唯一峰值 \\(x_i\\)，越远离峰效用越低——单峰。则对任意一对 \\(x,y\\)，多数偏好与中位人 \\(m\\) 的偏好一致：\\(x\\) 与 \\(y\\) 谁离 \\(x_m\\) 近，谁赢。故 \\(x_m\\) 击败一切挑战者。缺口不是再证不可能，而是：<strong>限制定义域之后，多数不再需要 IIA 与传递去「加总」，它直接选出一个点。</strong></p><p>Downs：两个追求胜选的政党，同时选政纲，均衡是双双落在 \\(x_m\\)——霍特林在政治光谱上的版本，但这里选民投票不是买商品，政党目标是得票不是利润。</p><h3 id="单峰不是「大家都温和」" tabindex="-1">单峰不是「大家都温和」 <a class="header-anchor" href="#单峰不是「大家都温和」" aria-label="Permalink to &quot;单峰不是「大家都温和」&quot;">​</a></h3><p>单峰允许极端峰。中位是分布的中位，不是均值。偏斜的偏好分布让 \\(x_m\\) 离开平均理想点。多峰（对两端都喜欢、讨厌中间）立刻回到循环——下一课。单峰是定义域限制，不是人际比较，也不给出 Arrow 的 \\(W\\)；它只让多数有解。</p><p><span class="marginnote">单峰可以直译成「离我的理想点越远越不满意」：政策排成一条线，满意度从自己的峰值向两边单调下滑。它不要求大家温和——你的峰可以放在极左或极右，只要越远离峰越不满，就仍是单峰，中位定理照常成立。</span></p><p><span class="marginnote">Black 1948 在委员会里证明中位胜者。Hotelling 1929 的线性城市是空间竞争；Downs 1957 明确写成民主政党。引用中位选民时声明：一维加单峰，不是任意政策空间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把个人理想点排序，\\(x_{(1)}\\le\\cdots\\le x_{(n)}\\)，中位 \\(x_m\\)。任意 \\(y\\lt x_m\\)，所有 \\(i\\ge m\\) 偏好 \\(x_m\\)；对称地 \\(y\\gt x_m\\)。多数成立。两党 Bertrand 式选点：偏离 \\(x_m\\) 把中位一侧的选票让给对手，故纳什是 \\((x_m,x_m)\\)。</p><p>公共品供给若只用多数定 \\(G\\)，则 \\(G\\) 反映 \\(x_m\\) 的 MRS，而不是萨缪尔森加总——中位一般不是 \\(\\sum\\mathrm{MRS}=\\mathrm{MRT}\\) 的那个 \\(G\\)。再分配的 \\(T(\\cdot)\\) 若被压成一维「多大」，中位人的理想再分配不必等于 Mirrlees 计划。多数执行的是中位峰，不是加权福利最大。</p><p><span class="marginnote">初学者容易把「中位选民决定 \\(G\\)」当成有效率的结果。多数规则只执行中位一个人的边际评价；萨缪尔森条件要求把所有人的边际评价加总。两者一般不相等：中位供给可能过多也可能过少——这是分配问题冒充效率问题的典型场景。</span></p>',14)),(o(),n(i,null,{default:E(()=>[l(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E6%97%A0%E9%99%90%E5%88%B6%E5%9F%9F%E4%B8%8D%E5%8F%AF%E8%83%BD%22%5D%20--%3E%20SP%5B%22%E9%99%90%E5%AE%9A%E4%B9%89%E5%9F%9F%EF%BC%9A%E4%B8%80%E7%BB%B4%E5%8D%95%E5%B3%B0%22%5D%0A%20%20SP%20--%3E%20MED%5B%22%E5%A4%9A%E6%95%B0%E8%83%9C%E8%80%85%20%3D%20%E4%B8%AD%E4%BD%8D%E5%B3%B0%22%5D%0A%20%20MED%20--%3E%20DOWN%5B%22%E4%B8%A4%E5%85%9A%E6%94%B6%E6%95%9B%E5%88%B0%20x_m%22%5D%0A%20%20SP%20--%3E%20CYC%5B%22%E9%9D%9E%E5%8D%95%E5%B3%B0%EF%BC%9A%E4%B8%8B%E4%B8%80%E8%AF%BE%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"本课不引入概率投票、党派意识形态约束。那些改收敛程度，不改「单峰才有中位胜者」这一刀。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"多数等于中位偏好的机制是成对切割：一维线上，任何挑战点都把选民分成「左侧一块、右侧一块」，中位所在的那一块至少一半。单峰保证没有人跳过中间去支持更远的点。两党收敛的机制是对称抢中间：左偏政纲把中位输给仍停在 \\(x_m\\) 的对手。",-1)),(o(),n(i,null,{default:E(()=>[l(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%8C%91%E6%88%98%E7%82%B9%20y%20%E8%90%BD%E5%9C%A8%20x_m%20%E4%B8%80%E4%BE%A7%22%5D%20--%3E%20CUT%5B%22%E9%80%89%E6%B0%91%E6%8C%89%E5%B3%B0%E4%BD%8D%E5%88%87%E6%88%90%E4%B8%A4%E5%9D%97%22%5D%0A%20%20CUT%20--%3E%20MAJ%5B%22%E4%B8%AD%E4%BD%8D%E6%89%80%E5%9C%A8%E9%82%A3%E4%B8%80%E5%9D%97%E8%87%B3%E5%B0%91%E5%8D%A0%E4%B8%80%E5%8D%8A%22%5D%0A%20%20MAJ%20--%3E%20CLOSER%5B%22%E5%8D%95%E5%B3%B0%3A%20%E8%BF%99%E5%9D%97%E9%87%8C%E6%B2%A1%E4%BA%BA%E8%B6%8A%E8%BF%87%20x_m%20%E5%8E%BB%E6%94%AF%E6%8C%81%E6%9B%B4%E8%BF%9C%E7%9A%84%20y%22%5D%0A%20%20CLOSER%20--%3E%20WIN%5B%22x_m%20%E6%88%90%E5%AF%B9%E5%87%BB%E8%B4%A5%E4%B8%80%E5%88%87%20y%3A%20Condorcet%20%E8%83%9C%E8%80%85%22%5D%0A%20%20WIN%20--%3E%20PARTY%5B%22%E4%B8%A4%E5%85%9A%E5%90%8C%E6%AC%BE%E9%80%BB%E8%BE%91%3A%20%E8%B0%81%E5%81%8F%E7%A6%BB%E8%B0%81%E6%8A%8A%E4%B8%AD%E9%97%B4%E8%AE%A9%E7%BB%99%E5%AF%B9%E6%89%8B%22%5D%0A%20%20PARTY%20--%3E%20EQ%5B%22%E7%BA%B3%E4%BB%80%E5%9D%87%E8%A1%A1%3A%20%E5%8F%8C%E5%8F%8C%E5%81%9C%E5%9C%A8%20x_m%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>与 Arrow 的关系：单峰扔掉无限制域，多数满足帕累托与非独裁，并在这一域上传递（至少给出最大元）。IIA 在两两多数上本来就满足。不可能被域限制解除，不是被「民主」口号解除。</p><p>公共支出与税率若被压成一维，中位人的理想 \\(G\\) 随收入分布变：中位相对均值越穷，越要更多再分配——这是实证政治经济学的比较静态，本课只承认它仍需要单峰。一旦政策有两维（税率加管制），中位在每个轴上可以指向不同点，循环下一课立刻回来。</p><p><span class="marginnote">数字实例：9 个选民的理想点是 1,1,2,4,5,8,9,9,10，均值约 5.4，中位是排第 5 位的 5。让偏好最高的两人把峰抬到 20，均值被拉到约 6.8，中位仍停在 5——中位对尾部不敏感，这正是中位人常比「平均人」穷、再分配更容易过半的原因。</span></p><p><span class="marginnote">奇数选民避免中位平局。偶数时中位是一段，多数可在中位区间内平。多维政策空间里单峰不够，中位在每个方向上可以不一致——下一课循环与 McKelvey。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>弃权若与距理想点的距离相关，有效中位会移向投票率更高的一侧。</p><p>议程控制、弃权、两维以上（税率加管制），中位定理失败。政党要募资、有意识形态，收敛不完全：政纲可以停在中位两侧，分化来自承诺或选民不确定。下一课专写单峰失败时多数的循环。市场失灵课序用投票来定公共品与税时，必须声明是否在单峰世界。</p><p>后课默认：一维单峰下，多数的 Condorcet 胜者是中位理想点；两党竞争把它当成政纲。这不是 Arrow 的社会排序，只是受限域上的选择。</p><p>本课不把中位供给写成萨缪尔森条件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单峰把无限制域拿掉，多数有胜者，即中位峰。</li><li>两党为得票把政纲收到同一点。</li><li>中位供给不必等于萨缪尔森或 Mirrlees。</li><li>下一课：偏好不是单峰时，两两多数可以转圈。</li><li>出处：Black, <em>JPE</em>, 1948；Downs, 1957。</li></ul>',11))])}const f=s(p,[["render",d]]);export{u as __pageData,f as default};
